#!/usr/bin/env bash
# benchmark_overnight_gpu.sh — Overnight convergence-vs-pLDDT benchmark on a GPU.
#
# Pipeline per protein (defined in benchmark_one_protein.sh):
#   ESMFold → train 47-layer probes → MDS reconstruction → distance correlations
# Then this script aggregates and produces the final figures.
#
# Design choices (defensible against reviewer scrutiny):
#   • Test set heavily weighted toward FAILURE cases (the discriminating class)
#   • CASP15 free-modeling targets used as failure pool (published held-out set)
#   • Anchor controls = small classic proteins (ubiquitin, myoglobin) for sanity
#   • Selection criteria documented in benchmark_proteins.json
#   • Failures classified by failure MODE (shallow MSA, novel topology, etc.)
#     to test cross-mode generalization of the metric
#
# Usage on the GPU instance:
#   bash scripts/benchmark_overnight_gpu.sh
#
# Total runtime estimate: ~6-8 hours for ~15 proteins at 400 steps/layer
#
# CAUTION: this script ASSUMES the user has already downloaded missing
# CASP15 sequences and ground-truth PDBs into data/casp15/. The script will
# SKIP proteins whose files are not present rather than fail the whole batch.
set -euo pipefail

PROJECT="${PROJECT:-rugged-weaver-406003}"
INSTANCE="${INSTANCE:-esmfold-l4-probes}"
ZONE="${ZONE:-us-west1-a}"
REMOTE_DIR="${REMOTE_DIR:-~/recurrent-protein-folding}"

# ── Sync code ─────────────────────────────────────────────────────────────────
echo "==> Syncing code + data to $INSTANCE"
gcloud compute scp --recurse \
    pyproject.toml README.md recurrent_folding scripts data \
    "$INSTANCE:$REMOTE_DIR" \
    --project "$PROJECT" --zone "$ZONE"

# ── Run the batch ─────────────────────────────────────────────────────────────
gcloud compute ssh "$INSTANCE" --project "$PROJECT" --zone "$ZONE" --command "
    set -euo pipefail
    cd $REMOTE_DIR
    export PATH=\"\$HOME/.local/bin:\$PATH\"
    chmod +x scripts/benchmark_one_protein.sh

    echo '=========================================================='
    echo 'OVERNIGHT BENCHMARK: convergence dynamics vs pLDDT'
    echo 'Start: '\$(date)
    echo '=========================================================='

    # === Protein registry ===
    # Format:   NAME|SEQUENCE|GT_PDB|GT_CHAIN|CLASS
    # CLASS is for annotation only; the metric doesn't see it.
    # If GT_PDB doesn't exist, the protein is SKIPPED with a warning.

    # NOTE: T1137 sequences listed inline since they're public CASP15 targets;
    # ubiquitin/myoglobin sequences are inline; longer ones reference local PDBs.
    declare -a PROTEINS=(
        'ubq|MQIFVKTLTGKTITLEVEPSDTIENVKAKIQDKEGIPPDQQRLIFAGKQLEDGRTLSDYNIQKESTLHLVLRLRGG|data/1UBQ.pdb|A|success'

        'mbn|VLSEGEWQLVLHVWAKVEADVAGHGQDILIRLFKSHPETLEKFDRFKHLKTEAEMKASEDLKKHGVTVLTALGAILKKKGHHEAELKPLAQSHATKHKIPIKYLEFISEAIIHVLHSRHPGDFGADAQGAMNKALELFRKDIAAKYKELGYQG|data/1MBN.pdb|A|success'

        '8fmi|GMTEYKLVVVGAGGVGKSALTIQLIQNHFVDEYDPTIEDSYRKQVVIDGETCLLDILDTAGQEEYSAMRDQYMRTGEGFLCVFAINNTKSFEDIHHYREQIKRVKDSEDVPMVLVGNKSDLPSRTVDTKQAQDLARSYGIPFIETSAKTRQGVDDAFYTLVREIRKHKEK|data/8FMI.pdb|A|success'

        'T1137s4||data/casp15/T1137/T1137s4.pdb| |failure_shallow_msa'

        'T1137s6||data/casp15/T1137/T1137s6.pdb| |failure_novel_topology'

        'T1104|QLEDSEVEAVAKGLEEYANGVTEDNFKNYVKNNFAQQEISSVEEELNVNISDSCVANKIKDEFFAISISAIVKAAQKKAWKELAVTVLRFAKANGLKTNAIIVAGQLALWAVQCG|data/casp15_rcsb/T1104.pdb|A|casp15_unknown'

        'T1120|PLTLNFGSVRLPVSADGLLHAPTAQQQLGLTQSWEAALVEHGLPETYRDFGAGPEAAVSVPDFVALAFALDTPEARRWQKRARELLARAMQGDVRVAAQIAERNPEPDARRWLAARLESTGARRELLATVARHGGEGRVYGQLGSISNRTVLGKVKATRDGLTSAELLRLAYIDTVTARAIQESEARGNAAILTLHEQVARSERQSWERAGQVQ|data/casp15_rcsb/T1120.pdb|A|casp15_unknown'

        'T1122|LCNDYGYEPNVDYPNASHAGLYDRSKQPYVDTAIGPKTTIQFDHVFIKSDFKTWLAHNQDEAILLIRLYELGLLLQGRSDSFLEFYNNTTYITRTDSKQPFLNKYGKLVDTTSVTCLDIFLSVVLFALNQIDSLICDFKNTPWINLSKEHKKIYELVRGIFGICYGERFEYCPFDANSTASALNVNATLNAKKTIELITCGLIRALIAYANLVTAFSADKTALLHEILLT|data/casp15_rcsb/T1122.pdb|A|casp15_unknown'

        'T1124||data/casp15_rcsb/T1124.pdb|A|casp15_unknown'

        'T1132|MTYHVLVQFDVPSDKREAFAAAGLFDANGSLQNEPGTLRFEVIRDENNRNRFYLDEVYEDEAAFLQHRNETIARFYELIDSYAFGPLFLFKGYRVEG|data/casp15_rcsb/T1132.pdb|A|casp15_unknown'

        'T1147|DPKVVTYEIFGTPGAVVDINYLDLDARTQRVNDVTLPWSITLSTTAPSALAHIVAQGNADHIGCRIIVDGELRVESVSTGVNAQTYCIEKSA|data/casp15_rcsb/T1147.pdb|A|casp15_unknown'

        'T1155|MGYSDEDREADNLRIAEIIKNAQDDDSKINSTQELLDIYRRLYPSLTPEERESIDKFVNEHTDAIIIDGVPIQGGRKARIVGKIVSPGVKGLATGFFEELGSKLAQLFAGENLYFQ|data/casp15_rcsb/T1155.pdb|A|casp15_unknown'

        'T1159|MNLTEKGTKTAKLSASDRIIYADNHLIHGPDDITAYMKGVCYDAAAYMRYLYNAKISFDQLTSISAQNWLPVFKFAEGRMWDGRNSLPGGKAIGFCRVKGMEFFHAAVAVGGTEIRAINGGLLGAGWLHPVDLRKVLTQKNPDGSFKYDGTDIFVYISNL|data/casp15_rcsb/T1159.pdb|A|casp15_unknown'

        'T1170||data/casp15_rcsb/T1170.pdb|A|casp15_unknown'

        'T1173|NASINFVATEAHTASAGGAKIIFNTTNNGATGSTEKVVIDQNGNVGVGVGAPTAKMDVNGGIKQPNYGIISAVRNSGGVTASMPWTNAYVLAHQGEMHQWVAGGPILQDSVTGCNAGPDAGVKFDSIATSWGGPYKVIFHTTGSNGAIHLEWSGWQVSLKNSAGTELAIGMGQVFATLHYDPAVSNWRVEHMFGRINNTNFTCW|data/casp15_rcsb/T1173.pdb|A|casp15_unknown'

        'T1176|ADKILDLSFKKIETDLSSKITYEDTGVKIETDSSKSDKERYLYIYQNIKENWSYNNFYIEIQNKNKSSQKINLSIQSKNFEFRLKEGSEVFLEGKNIIYSDKIKEGIEVPGEFEGKIYVNFNSLINEESNVVLDSNLSNIVSWGITFIPSDEEHNIVIIKKISLLSE|data/casp15_rcsb/T1176.pdb|A|casp15_unknown'

        'T1183||data/casp15_rcsb/T1183.pdb|A|casp15_unknown'

        'T1194|AAGFVETAGNACEWTPGRYELSETEGRVRIPNGLYVKKEETSKIARGSCTFALTLKAPAGKKIVVRDSQQLISLRAYPQQTRVKAEVEIFKAGSQGAKQTLEIVAAEKAEKTTQYVGQKDVLLETACGGSDILRGNLSATIIGEGKGRAFAKNVTLDIQEVDCNLE|data/casp15_rcsb/T1194.pdb|A|casp15_unknown'


        '1AO6||data/1AO6.pdb|A|success_large'

        '7ACN||data/pdb_targets/7acn.pdb|A|success_large'
    )

    success_list=()
    fail_list=()

    for entry in \"\${PROTEINS[@]}\"; do
        IFS='|' read -r NAME SEQ GT_PDB GT_CHAIN CLASS <<< \"\$entry\"

        echo ''
        echo '──────────────────────────────────────────────────────────'
        echo \"[\$NAME]  expected_class=\$CLASS\"

        if [ ! -f \"\$GT_PDB\" ]; then
            echo \"  SKIP: ground-truth PDB not found at \$GT_PDB\"
            fail_list+=(\"\$NAME (missing PDB)\")
            continue
        fi

        # If SEQ is empty, try to read from FASTA at parallel path
        if [ -z \"\$SEQ\" ]; then
            FASTA=\$(echo \"\$GT_PDB\" | sed 's/\\.pdb\$/.fasta/')
            if [ -f \"\$FASTA\" ]; then
                SEQ=\$(grep -v '^>' \"\$FASTA\" | tr -d '\\n')
                echo \"  read sequence (\${#SEQ} aa) from \$FASTA\"
            else
                echo \"  SKIP: SEQ empty and no FASTA at \$FASTA\"
                fail_list+=(\"\$NAME (missing FASTA)\")
                continue
            fi
        fi

        # Run the per-protein pipeline; tolerate per-protein failure
        if NAME=\"\$NAME\" SEQ=\"\$SEQ\" GT_PDB=\"\$GT_PDB\" GT_CHAIN=\"\$GT_CHAIN\" \\
                bash scripts/benchmark_one_protein.sh 2>&1 | tee -a runs/benchmark_overnight.log; then
            success_list+=(\"\$NAME\")
            echo \"  ✓ \$NAME done\"
        else
            fail_list+=(\"\$NAME (pipeline error)\")
            echo \"  ✗ \$NAME failed during pipeline; continuing\"
        fi
    done

    echo ''
    echo '=========================================================='
    echo 'BATCH COMPLETE  '\$(date)
    echo '=========================================================='
    echo \"Successful: \${#success_list[@]}\"
    for n in \"\${success_list[@]}\"; do echo \"  ✓ \$n\"; done
    echo \"Skipped/failed: \${#fail_list[@]}\"
    for n in \"\${fail_list[@]}\"; do echo \"  ✗ \$n\"; done
" 2>&1 | tee benchmark_overnight.local.log

# ── Aggregate locally ─────────────────────────────────────────────────────────
echo ""
echo "==> Downloading benchmark results"
gcloud compute scp --recurse \
    "$INSTANCE:$REMOTE_DIR/runs/benchmark_*" \
    runs/ \
    --project "$PROJECT" --zone "$ZONE" || echo "(some downloads may have failed)"

echo ""
echo "Done. Run scripts/aggregate_benchmark.py locally to produce the final figure."
